<script setup>
import {ref,computed,onBeforeUnmount,nextTick,watch} from 'vue'
import {Headset,Phone,ChevronDown,X,Check,Pause,Power,Delete,Settings2,Volume2} from 'lucide-vue-next'
import MicrophoneCheck from './MicrophoneCheck.vue'
const props=defineProps({status:{type:String,default:'offline'},queues:{type:Array,default:()=>[]},origins:{type:Array,default:()=>[]},selectedIds:{type:Array,default:()=>[]},busy:Boolean,error:String,occupied:Boolean,otherSession:Boolean,lastCall:Object,callProgress:Object,endingCall:Boolean,wrapup:Object,wrapupRemaining:{type:Number,default:0}})
const emit=defineEmits(['status','queues','dial','dial-open','diagnostic','clear-error','end-wrapup','hangup','open-operation'])
const popup=ref(''),chosen=ref([]),number=ref(''),dialOrigin=ref(''),trigger=ref(null),dialog=ref(null)
const labels={available:'Online',paused:'Pausado',offline:'Offline'}
const manualNumbers=computed(()=>props.origins)
const selectedManual=computed(()=>manualNumbers.value.find(o=>o.number===dialOrigin.value))
const onlineRoutes=computed(()=>(selectedManual.value?.routes||[]).filter(r=>props.selectedIds.includes(r.queue_id)))
const canDial=computed(()=>!props.busy&&!props.wrapupRemaining&&!props.occupied&&!props.otherSession&&props.status==='available'&&!!number.value&&onlineRoutes.value.length>0)
function dial(){if(canDial.value)emit('dial',{number:number.value,origin_number:dialOrigin.value})}
const queueKind=q=>q.whatsapp_numbers?.length&&!q.incoming_numbers?.length&&q.direction==='inbound'?'WhatsApp':({inbound:'Receptivo',outbound:'Saída',mixed:'Entrada e saída'})[q.direction]
async function open(kind,keepError=false){if(!keepError)emit('clear-error');popup.value=kind;if(kind==='queues')chosen.value=[...props.selectedIds];if(kind==='dial'&&!manualNumbers.value.some(o=>o.number===dialOrigin.value))dialOrigin.value=manualNumbers.value.find(o=>o.routes.some(r=>props.selectedIds.includes(r.queue_id)))?.number||manualNumbers.value[0]?.number||'';emit('dial-open',kind==='dial');await nextTick();dialog.value?.querySelector('button,input,select')?.focus()}
watch(()=>[props.callProgress?.state,props.lastCall?.id,props.busy,props.error],async()=>{await nextTick();if(popup.value==='dial'&&dialog.value){dialog.value.scrollTop=0;if(!dialog.value.contains(document.activeElement)||document.activeElement?.disabled)dialog.value.querySelector('.close-popover')?.focus()}})
function close(){popup.value='';emit('dial-open',false);trigger.value?.focus()}
function changeStatus(value){emit('status',value)}
function trap(e){if(e.key==='Escape'){e.preventDefault();close();return}if(e.key!=='Tab')return;const list=[...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href]')];if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
function digit(key){if(number.value.length<32)number.value+=key}
defineExpose({close,open})
onBeforeUnmount(()=>emit('dial-open',false))
</script>
<template><div class="agent-tools"><div class="availability-control"><button ref="trigger" class="headset-trigger" :class="status" aria-label="Status do atendimento" aria-haspopup="dialog" :aria-expanded="!!popup" @click="popup==='status'?close():open('status')"><span class="headset-icon"><Headset :size="23"/><i :class="status"/></span><span>{{otherSession?'Outra conexão':wrapupRemaining?'Pós-atendimento':labels[status]}}</span><ChevronDown :size="13"/></button><button class="manage-link" @click="open('queues')">Gerenciar filas</button></div><button class="dial-trigger" title="Discagem manual" aria-label="Abrir teclado de telefone" aria-haspopup="dialog" @click="open('dial')"><Phone :size="19"/></button>
 <Teleport to="body"><div v-if="popup" class="agent-popover-backdrop" @click.self="close"><section ref="dialog" class="agent-popover" role="dialog" aria-modal="true" :aria-label="({status:'Status do atendimento',queues:'Gerenciar filas',dial:'Discagem manual',audio:'Microfone e headset'})[popup]" @keydown="trap"><header><div><span class="eyebrow">SEU ATENDIMENTO</span><h2>{{({status:'Como você está?',queues:'Gerenciar filas',dial:'Fazer uma ligação',audio:'Microfone e headset'})[popup]}}</h2></div><button class="close-popover" aria-label="Fechar caixa de atendimento" @click="close"><X :size="19"/></button></header><p v-if="error" class="popover-error" role="alert">{{error}}</p>
 <div v-if="wrapupRemaining" class="session-hint" role="status"><strong>Pós-atendimento · {{Math.floor(wrapupRemaining/60)}}:{{String(wrapupRemaining%60).padStart(2,'0')}}</strong><p>{{wrapup?.queue_name||'Fila de atendimento'}}. Aguarde a contagem antes de outra ligação.</p><button v-if="wrapup?.allow_early" class="secondary wide" :disabled="busy||occupied||otherSession" @click="emit('end-wrapup')">Encerrar pós-atendimento</button><small v-else>A fila exige cumprir todo o tempo.</small></div><p v-if="otherSession" class="session-hint" role="status"><strong>Seu atendimento está em outra conexão.</strong> Outra aba ou navegador com seu usuário ainda controla a disponibilidade. Use aquela aba ou fique offline nela. Se você já a fechou ou recarregou, aguarde até 90 segundos para ficar online aqui. Nenhuma conexão será encerrada automaticamente.</p><template v-if="popup==='status'"><p class="hint">Online ativa sua disponibilidade em todas as filas atribuídas. Filas progressivas habilitadas podem iniciar chamadas.</p><div class="status-options"><button :disabled="busy||otherSession" :aria-pressed="status==='available'" @click="changeStatus('available')"><span class="option-icon online"><Check :size="18"/></span><span><strong>Online</strong><small>Todas as minhas filas</small></span><span v-if="status==='available'" aria-hidden="true">●</span></button><button :disabled="busy||otherSession" :aria-pressed="status==='paused'" @click="changeStatus('paused')"><span class="option-icon pause"><Pause :size="18"/></span><span><strong>Pausado</strong><small>Concluir apenas o atendimento atual</small></span></button><button :disabled="busy||otherSession" :aria-pressed="status==='offline'" @click="changeStatus('offline')"><span class="option-icon"><Power :size="18"/></span><span><strong>Offline</strong><small>Indisponível para novas distribuições</small></span></button></div><div class="popover-footer"><button @click="open('queues')"><Settings2 :size="15"/> Gerenciar filas</button><button @click="open('audio')"><Volume2 :size="15"/> Conferir áudio</button></div></template>
 <template v-if="popup==='queues'"><p class="hint">Escolha onde deseja ficar online. Os vínculos e a habilitação das filas são definidos pelo administrador.</p><div class="queue-options"><label v-for="q in queues" :key="q.id"><input v-model="chosen" type="checkbox" :value="q.id" :disabled="busy"><span><strong>{{q.name}}</strong><small>{{queueKind(q)}}<template v-if="q.direction!=='inbound'"> · saída {{q.status==='running'?'habilitada':'pausada'}}</template><template v-if="q.incoming_numbers?.length"> · entrada {{q.inbound_enabled?'habilitada':'pausada'}}</template></small></span></label><p v-if="!queues.length">Nenhuma fila atribuída. Solicite o vínculo ao administrador.</p></div><div class="queue-select-actions"><button :disabled="busy" @click="chosen=queues.map(q=>q.id)">Selecionar todas</button><button :disabled="busy" @click="chosen=[]">Limpar</button></div><button class="primary wide" :disabled="busy||!queues.length" @click="emit('queues',chosen)">{{chosen.length?'Ficar online nas '+chosen.length+' fila(s)':'Ficar offline'}}</button></template>
 <template v-if="popup==='dial'"><div v-if="callProgress" :class="['dial-progress',callProgress.state]" role="status" aria-live="polite"><small>Chamada atual · {{callProgress.destination}}</small><strong><Phone :size="18"/> {{callProgress.title}}</strong><p>{{callProgress.detail}}</p><button v-if="callProgress.canHangup" class="hangup-call wide" :disabled="endingCall" @click="emit('hangup')">{{endingCall?'Encerrando…':'Encerrar ligação'}}</button><button v-if="callProgress.state==='completed'" class="secondary wide" @click="emit('open-operation')">Abrir tabulação</button></div><div v-else-if="busy" class="dial-progress" role="status"><strong>Preparando ligação…</strong><p>Verificando o microfone e a autorização para ligar.</p></div><div v-else-if="lastCall" class="session-hint" role="status"><small>Última chamada · {{lastCall.destination}}</small><strong>{{lastCall.title}}<template v-if="lastCall.elapsed_seconds!==null"> · {{lastCall.elapsed_seconds}} s</template></strong>{{lastCall.detail}}</div><p class="hint">Ligação manual para contato cadastrado e autorizado. Não inicia cadência nem WhatsApp automático.</p><label class="dial-label">Número de saída<select v-model="dialOrigin" aria-label="Número de saída" :disabled="busy||occupied"><option value="">Selecione um número</option><option v-for="o in manualNumbers" :key="o.number" :value="o.number">{{o.number}}</option></select></label><p v-if="selectedManual" class="hint">Este número aparecerá para o cliente. As permissões vêm das suas filas vinculadas.</p><p v-if="onlineRoutes.length" class="hint">Fixos {{onlineRoutes.some(r=>r.allow_landline)?'permitidos':'bloqueados'}} · celulares {{onlineRoutes.some(r=>r.allow_mobile)?'permitidos':'bloqueados'}}.</p><div class="dial-input"><input v-model="number" type="tel" inputmode="tel" aria-label="Telefone para discar" placeholder="DDD + telefone" maxlength="32" :disabled="busy||occupied" @keydown.enter.prevent="dial"><button aria-label="Apagar último dígito" :disabled="busy||occupied" @click="number=number.slice(0,-1)"><Delete :size="19"/></button></div><div class="dial-keys"><button v-for="[key,letters] in [['1',''],['2','ABC'],['3','DEF'],['4','GHI'],['5','JKL'],['6','MNO'],['7','PQRS'],['8','TUV'],['9','WXYZ'],['+','DDI'],['0',''],['⌫','APAGAR']]" :key="key" :aria-label="key==='⌫'?'Apagar dígito':key" :disabled="busy||occupied" @click="key==='⌫'?number=number.slice(0,-1):digit(key)"><strong>{{key}}</strong><small>{{letters||' '}}</small></button></div><p v-if="!manualNumbers.length" class="hint">Nenhum número de saída habilitado. O administrador deve vincular um número autorizado a uma das suas filas e permitir discagem manual.</p><p v-else-if="status!=='available'" class="hint">Fique online antes de ligar.</p><p v-else-if="otherSession" class="hint">Sua disponibilidade está sendo controlada em outra aba. Use o teclado daquela aba ou fique offline nela primeiro.</p><p v-else-if="!onlineRoutes.length" class="hint">Fique online em uma fila vinculada a este número, em Gerenciar filas.</p><p v-else-if="occupied" class="hint">Conclua o atendimento ou a tabulação atual.</p><button class="primary wide" :disabled="!canDial" @click="dial"><Phone :size="17"/> Ligar</button></template>
 <template v-if="popup==='audio'"><MicrophoneCheck :disabled="busy||occupied"/><button class="secondary wide" @click="close();emit('diagnostic')">Abrir diagnóstico de áudio</button></template><p v-if="busy" role="status" class="hint">Preparando seu atendimento…</p>
 </section></div></Teleport>
</div></template>
<style scoped>
.agent-tools{display:flex;align-items:center;gap:14px}.availability-control{display:flex;flex-direction:column;align-items:center;gap:2px}.headset-trigger{display:flex;align-items:center;gap:9px;color:#626c59;padding:3px 6px;font-size:12px}.headset-trigger.available{color:#35755a}.headset-trigger.paused{color:#a57724}.headset-icon{position:relative;display:flex}.headset-icon i{position:absolute;right:-2px;bottom:-1px;width:8px;height:8px;border:2px solid white;border-radius:50%;background:#9da397}.headset-icon i.available{background:#389265}.headset-icon i.paused{background:#cca148}.manage-link{font-size:10px;color:#8e702d;padding:2px 5px}.dial-trigger{display:grid;place-items:center;width:36px;height:36px;border:1px solid #e1e3d7;border-radius:11px;background:white;color:#a47b28}.agent-popover-backdrop{position:fixed;inset:0;z-index:1800;background:#171d1622}.agent-popover{position:absolute;top:78px;right:26px;width:min(370px,calc(100vw - 30px));max-height:calc(100dvh - 100px);overflow:auto;background:#fff;border:1px solid #e0e2d5;border-radius:18px;box-shadow:0 20px 65px #1a261b2b;padding:23px;color:#303a29}.agent-popover header{display:flex;align-items:start;justify-content:space-between;gap:10px;margin-bottom:14px}.agent-popover h2{font-size:20px;margin:7px 0 0}.close-popover{padding:5px;color:#727e67}.agent-popover .hint{font-size:12px;line-height:1.7;color:#76816b;margin:12px 0}.dial-progress{background:#fff7e5;border:1px solid #e9cd89;padding:15px;border-radius:12px;font-size:12px;line-height:1.6;margin-bottom:14px}.dial-progress strong{display:flex;align-items:center;gap:8px;font-size:15px;margin:8px 0}.dial-progress p{margin:8px 0}.dial-progress.answered,.dial-progress.completed{background:#eaf7ee;border-color:#aed8b9;color:#27663e}.dial-progress .hangup-call{display:flex;background:#a83732;color:white;border-radius:9px;padding:11px;margin-top:14px;font-weight:600}.session-hint{background:#faf3df;border:1px solid #ead7a8;border-radius:10px;padding:12px;font-size:12px;line-height:1.6;color:#765c27}.session-hint strong{display:block;margin-bottom:5px}.popover-error{background:#fff0ee;border-radius:9px;padding:12px;font-size:12px;color:#973c32;line-height:1.6}.status-options{display:grid;gap:5px}.status-options>button{display:flex;align-items:center;gap:12px;text-align:left;padding:12px 8px;border-radius:10px}.status-options>button:hover{background:#f6f6ef}.status-options>button>span:nth-child(2){flex:1;display:grid;gap:4px}.status-options strong{font-size:13px}.status-options small{font-size:11px;color:#7b836f}.option-icon{display:grid;place-items:center;background:#f0f1eb;color:#7f8974;border-radius:10px;width:36px;height:36px}.option-icon.online{background:#e7f3ec;color:#39835d}.option-icon.pause{background:#fcf1d9;color:#ac832e}.popover-footer{border-top:1px solid #e8e9df;display:flex;justify-content:space-between;gap:8px;margin-top:15px;padding-top:14px}.popover-footer button{display:flex;gap:7px;align-items:center;font-size:11px;color:#7f713d}.queue-options{max-height:330px;overflow:auto}.queue-options label{display:flex;flex-direction:row;align-items:flex-start;margin:0;gap:10px;padding:13px 0;border-bottom:1px solid #f0f0e9}.queue-options input{width:16px;min-width:16px;height:16px;padding:0;margin:3px 0 0;flex-shrink:0;accent-color:#bd9134}.queue-options strong{font-size:12px;line-height:1.6}.queue-options small{display:block;font-size:10px;color:#7c856e;line-height:1.7;margin-top:4px}.queue-select-actions{display:flex;justify-content:space-between;margin:14px 0 20px;font-size:11px;color:#96712b}.agent-popover .wide{width:100%;justify-content:center}.dial-label{display:grid;gap:7px;font-size:11px;margin:15px 0}.dial-label select{width:100%;min-width:0;max-width:100%;font-size:11px;padding:10px;border:1px solid #dedfd4;border-radius:9px;background:white}.dial-input{display:flex;align-items:center;border:1px solid #dedfd4;border-radius:11px;padding:5px 10px}.dial-input input{min-width:0;width:100%;border:0;box-shadow:none;text-align:center;font-size:22px;letter-spacing:1px;padding:12px 0}.dial-input button{color:#8a917f}.dial-keys{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:17px 0}.dial-keys button{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:10px;border-radius:12px;background:#f7f7f1;color:#46533a;min-height:61px}.dial-keys button:hover{background:#f4ead3}.dial-keys strong{font-size:23px;font-weight:500}.dial-keys small{font-size:8px;letter-spacing:1.7px}.agent-popover button:disabled{opacity:.5;cursor:default}.agent-popover :deep(.microphone-check){padding:0;border:0;margin:0}.agent-popover :deep(.microphone-check h3){display:none}@media(max-width:680px){.agent-popover{top:75px;right:15px;padding:19px}.agent-tools{gap:8px}.headset-trigger{gap:5px;font-size:11px}}
</style>
